css:
.container {
  width: 100%;
  height: 100vh;
  --color1: rgb(255, 206, 84);
  --color2: rgb(72, 85, 99);
  background-color: var(--color1);
  background-image: linear-gradient(
      45deg,
      var(--color2) 25%,
      transparent 25%,
      transparent 75%,
      var(--color2) 75%
    ),
    linear-gradient(
      45deg,
      transparent 25%,
      var(--color1) 25%,
      var(--color1) 75%,
      transparent 75%
    ),
    linear-gradient(to bottom, rgba(0, 0, 0, 0.1), rgba(0, 0, 0, 0.1));
  background-size:
    80px 80px,
    80px 80px,
    100% 100%;
  background-position:
    0 0,
    40px 40px,
    0 0;
}
